// State pattern for ATM states
interface ATMState {
  void insertCard(ATM atm, Card card);
  void enterPin(ATM atm, int pin);
  void selectAction(ATM atm, ATMAction action);
  void dispense(ATM atm, double amount);
  void ejectCard(ATM atm);
}

// States:
// IdleState: accepts card insertion only
// CardInsertedState: awaits PIN
// AuthenticatedState: user can select action
// DispensingState: processing withdrawal

public class ATM {
  private ATMState currentState;
  private Card currentCard;
  private CashDispenser cashDispenser;
  // state transitions via setState()
}

class IdleState implements ATMState {
  public void insertCard(ATM atm, Card card) {
    atm.setCurrentCard(card);
    atm.setState(new CardInsertedState());
  }
  public void enterPin(ATM atm, int pin) {
    System.out.println("Please insert card first");
  }
  // other operations do nothing or show error
}

class CardInsertedState implements ATMState {
  public void insertCard(ATM atm, Card card) {
    System.out.println("Card already inserted");
  }
  public void enterPin(ATM atm, int pin) {
    if (atm.getBankServer().verifyPin(atm.getCurrentCard(), pin)) {
      atm.setState(new AuthenticatedState());
    } else {
      // handle wrong PIN, limit attempts
    }
  }
}

public class CashDispenser {
  // TreeMap keeps denominations sorted descending
  private final TreeMap<Integer, Integer> denominations;

  public Map<Integer, Integer> dispense(int amount) {
    Map<Integer, Integer> result = new LinkedHashMap<>();
    int remaining = amount;

    for (int denom : denominations.descendingKeySet()) {
      int count = Math.min(remaining / denom, denominations.get(denom));
      if (count > 0) {
        result.put(denom, count);
        remaining -= count * denom;
      }
    }
    if (remaining > 0) throw new InsufficientCashException();
    // update denomination counts
    return result;
  }
}
